68	                    };
69	                    next_event
70	                } else {
71	                    next_event
72	                };
73	                if keyval_event.kind() != EventKind::KeyValSep {
74	                    break;
75	                }
76	
77	                if input
78	                    .first()
79	                    .map(|e| e.kind() == EventKind::Whitespace)
80	                    .unwrap_or(false)
